command:
$ErrorActionPreference = "Stop"
Write-Host "===== CLEAN BOOKMARK PRE-MAIN ACCEPTANCE ====="
git fetch origin main work/bookmarks-winui --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "git fetch failed" }
$expected="5228cbbfc24f56d61a84975545f1d8572e7deece"
if ((git rev-parse origin/main).Trim() -ne $expected) { throw "main moved" }
$status=@(git status --short)
if($status.Count -ne 0){$status|%{Write-Host $_};throw "unexpected local changes"}
git checkout work/bookmarks-winui
if ($LASTEXITCODE -ne 0) { throw "checkout failed" }
git merge --ff-only origin/work/bookmarks-winui
if ($LASTEXITCODE -ne 0) { throw "work branch ff failed" }
Write-Host "BOOKMARK_HEAD=$(git rev-parse HEAD)"

Write-Host "SOURCE"
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source failed" }

Write-Host "M20_RELEASE_NATIVE"
cmd /c tests\winui\m20\build.cmd Release
if ($LASTEXITCODE -ne 0) { throw "M20 build failed" }
cmd /c "set FLY_M20_CONFIG=Release&& python -X utf8 tests\winui\m20\test_native.py"
if ($LASTEXITCODE -ne 0) { throw "M20 native failed" }

Write-Host "FULL_OWNED_RELEASE_GUI"
python -X utf8 tools\winui\run_checks.py gui --configuration Release
if ($LASTEXITCODE -ne 0) { throw "full owned Release GUI failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }
Write-Host "STATUS"
git status --short
Write-Host "CLEAN_BOOKMARK_PREMAIN_ACCEPTANCE_PASS"
